import {ToggleSwitch} from '@primer/react'
import styles from './PullRequestToggleAddon.module.css'

export interface PullRequestToggleAddonProps {
  checked: boolean
  onChange: (checked: boolean) => void
}

export function PullRequestToggleAddon({checked, onChange}: PullRequestToggleAddonProps) {
  return (
    <div className={styles.container}>
      <span id="create-pull-request-toggle-label" className={styles.label}>
        Create a pull request
      </span>
      <ToggleSwitch
        size="small"
        aria-labelledby="create-pull-request-toggle-label"
        checked={checked}
        onClick={() => onChange(!checked)}
        statusLabelPosition="end"
      />
    </div>
  )
}
